def forward(groups):
    date = groups[0]
    space = groups[1]
    time = groups[2]
    dt = datetime.strptime(date + time, '%y%m%d%H%M%S')
    space_length = len(space)
    return {'stored': [int(dt.timestamp() * 1000000), space_length], 'layout': []}

def inverse(record):
    micros = record['stored'][0]
    space_length = record['stored'][1]
    dt = datetime.fromtimestamp(micros / 1000000)
    space = ' ' * space_length
    return dt.strftime('%y%m%d') + space + dt.strftime('%H%M%S')
